import{_ as a,o,c as t,a5 as i}from"./chunks/framework.DOB-AMqW.js";const k=JSON.parse('{"title":"Link Deck Data Collection","description":"Official data-collection information for Link Deck.","frontmatter":{"title":"Link Deck Data Collection","description":"Official data-collection information for Link Deck.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/link-deck.md","filePath":"data-collection/link-deck.md"}'),l={name:"data-collection/link-deck.md"};function r(n,e,s,c,d,f){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="link-deck-data-collection" tabindex="-1">Link Deck Data Collection <a class="header-anchor" href="#link-deck-data-collection" aria-label="Permalink to &quot;Link Deck Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 1, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Link Deck stores profiles, folders, bookmark URLs and details, notes, tags, favourites, archive and trash status, favicons, visit metadata, and preferences in SQLite on Android or IndexedDB in a browser. A PIN is stored only as a salted PBKDF2 verifier. Android handles biometric verification without giving Link Deck biometric templates.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>Link Deck has no account, developer cloud, analytics, advertising, crash reporting, or tracking service. The developer does not receive the local bookmark database or usage data. If you email support, the developer receives only what you choose to include.</p><h2 id="data-processed-outside-local-storage" tabindex="-1">Data processed outside local storage <a class="header-anchor" href="#data-processed-outside-local-storage" aria-label="Permalink to &quot;Data processed outside local storage&quot;">​</a></h2><ul><li>Google&#39;s favicon service receives a saved website hostname when its icon is requested.</li><li>Google may receive normal connection metadata for favicon and font requests.</li><li>Saved websites and the selected browser receive a URL when you open it.</li><li>A file or sharing provider you choose receives backups or bookmark exports sent to it.</li></ul><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',10)])])}const p=a(l,[["render",r]]);export{k as __pageData,p as default};
